from typing import List, Dict, Any
import csv
import io
import re
from collections import Counter

def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.split("\n")
    nonempty = [ln for ln in lines if ln.strip() != ""]
    if not nonempty:
        return {"columns": [], "rows": []}

    delim = "\t"
    quotechar = '"'

    def split_physical(line: str) -> List[str]:
        return line.split(delim)

    def count_fields(line: str) -> int:
        return len(split_physical(line))

    header_idx = None
    for i, ln in enumerate(lines):
        if ln.strip() == "":
            continue
        if count_fields(ln) >= 2:
            header_idx = i
            break
    if header_idx is None:
        return {"columns": [], "rows": []}

    def parse_with_csv(s: str) -> List[List[str]]:
        reader = csv.reader(io.StringIO(s), delimiter=delim, quotechar=quotechar, doublequote=True, skipinitialspace=False)
        return [row for row in reader]

    rows = parse_with_csv(text)
    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    if len(header) == 1 and delim in header[0]:
        header = [c.strip() for c in header[0].split(delim)]

    width = max(len(header), 1)
    cleaned_rows = []
    for row in data_rows:
        if len(row) == 0:
            continue
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width-1] + [delim.join(row[width-1:])]
        cleaned_rows.append([str(v) for v in row])

    header = [str(v) for v in header]
    if len(header) < width:
        header = header + [f"column_{i+1}" for i in range(len(header), width)]
    elif len(header) > width:
        width = len(header)
        cleaned_rows = [r + [""] * (width - len(r)) if len(r) < width else r[:width] for r in cleaned_rows]

    return {"columns": header, "rows": cleaned_rows}
